using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline runs the original per-call lookup in a loop over one shared context;
// Optimized runs the agent-owned HotLookupSolution.Lookup in the same loop. Both
// hit the same primary-key index and return the same rows, so the only thing that
// can differ is the per-call query-construction cost. Do not edit this file —
// edit Scenarios/HotLookup.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class HotLookupBenchmark
{
    private SqliteConnection _connection = null!;
    private int[] _ids = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedProducts(db, products: 5000, categories: 20, descriptionChars: 64, thumbnailBytes: 0);

        // A fixed, repeated set of ids simulates the same hot lookup running once
        // per request. 250 calls per invocation keeps the per-call translation
        // cost (what a compiled query removes) well above benchmark noise.
        var rng = new Random(11);
        _ids = Enumerable.Range(0, 250).Select(_ => rng.Next(1, 5001)).ToArray();

        EquivalenceGuard.SameResults(Baseline(), Optimized(), p => p.Id.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<ProductListItem> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var results = new List<ProductListItem>(_ids.Length);
        foreach (var id in _ids)
        {
            results.Add(db.Products
                .Where(p => p.Id == id)
                .Select(p => new ProductListItem(p.Id, p.Name, p.Price))
                .First());
        }

        return results;
    }

    [Benchmark]
    public List<ProductListItem> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        var results = new List<ProductListItem>(_ids.Length);
        foreach (var id in _ids)
        {
            results.Add(HotLookupSolution.Lookup(db, id));
        }

        return results;
    }
}
